sql.where:
      d.is_deleted = false AND dc.is_deleted = false

      
      
        AND d.shop_id = #{currentUserShopId}
      

      
        AND (d.drink_name ILIKE '%' || #{search} || '%' OR dc.category_name ILIKE '%' || #{search} || '%')

mapper.select:
WITH paged_drinks AS ( SELECT DISTINCT d.drink_id FROM drinks AS d JOIN drink_categories AS dc ON d.drink_category_id = dc.drink_category_id
ORDER BY d.drink_id
${sortDirection}
LIMIT #{size} OFFSET #{offset} ) SELECT d.drink_id, d.drink_category_id, d.drink_name, dd.size, TO_CHAR(dd.price, 'FM999,999,999') || 'đ' AS price, d.image_url, CASE WHEN d.status = 1 THEN 'Đang bán' WHEN d.status = 0 THEN 'Ngừng bán' ELSE 'Không xác định' END AS status, d.is_deleted FROM paged_drinks AS pd JOIN drinks AS d ON pd.drink_id = d.drink_id JOIN drink_details AS dd ON d.drink_id = dd.drink_id JOIN drink_categories AS dc ON d.drink_category_id = dc.drink_category_id ORDER BY d.drink_id
${sortDirection}
, CASE WHEN dd.size = 'S' THEN 1 WHEN dd.size = 'M' THEN 2 WHEN dd.size = 'L' THEN 3 ELSE 4 END ASC
